import assert from 'node:assert/strict'; import { execFileSync, spawn, spawnSync } from 'node:child_process'; import { mkdtemp, readFile } from 'node:fs/promises'; import net from 'node:net'; import { tmpdir } from 'node:os'; import path from 'node:path'; import test from 'node:test';
async function port(){const s=net.createServer();await new Promise((r)=>s.listen(0,'127.0.0.1',r));const p=s.address().port;await new Promise((r)=>s.close(r));return p;}
test('v0.4 local bundle installs SQLite HTTP/CLI/MCP/import surfaces and uninstalls without data removal',async(t)=>{execFileSync('npm',['run','bundle'],{stdio:'pipe'});const archive='release/viqueue-v0.4.0-rc.tar.gz';execFileSync('sha256sum',['-c',`${path.basename(archive)}.sha256`],{cwd:'release',stdio:'pipe'});const work=await mkdtemp(path.join(tmpdir(),'viq-bundle-'));execFileSync('tar',['-xzf',path.resolve(archive),'-C',work]);const bundle=path.join(work,'viqueue-v0.4.0-rc');assert.equal((await readFile(path.join(bundle,'SOURCE_COMMIT'),'utf8')).trim(),execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim());const prefix=path.join(work,'prefix');execFileSync('bash',[path.join(bundle,'install-local.sh')],{cwd:bundle,env:{...process.env,VIQ_PREFIX:prefix}});const listen=await port();const storage=path.join(work,'data','viqueue.sqlite');const server=spawn(path.join(prefix,'bin','viqueue-server'),[`--port=${listen}`,`--storage=${storage}`]);t.after(()=>server.kill());const base=`http://127.0.0.1:${listen}`;for(let i=0;i<100;i++){try{if((await fetch(`${base}/health`)).ok)break;}catch{}await new Promise((r)=>setTimeout(r,10));}const viq=(...a)=>spawnSync(path.join(prefix,'bin','viq'),['--server',base,'--json',...a],{encoding:'utf8'});assert.equal(viq('project','create','ABC').status,0);assert.equal(JSON.parse(viq('ticket','create','ABC','installed').stdout).ticket.id,'ABC-1');assert.equal((await fetch(base)).status,200);const mcp=spawnSync(path.join(prefix,'bin','viq-mcp'),[],{encoding:'utf8',env:{...process.env,VIQ_URL:base},input:'{"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}\n'});assert.equal(JSON.parse(mcp.stdout).result.serverInfo.version,'0.4.0');server.kill();execFileSync('bash',[path.join(bundle,'uninstall-local.sh')],{env:{...process.env,VIQ_PREFIX:prefix}});assert.equal(spawnSync(path.join(prefix,'bin','viq')).error?.code,'ENOENT');assert.equal(execFileSync('test',['-f',storage]).length,0);});
